import { useState, useEffect, useCallback, useMemo } from 'react';
import { scopedStorage, logger } from '@lark-apaas/client-toolkit-lite';

const STORAGE_KEY = '__app_ledlight_seo_settings';

export interface SeoPageSettings {
  id: string;
  pageKey: string; // 'home' | 'products' | 'about' | 'contact' | 'privacy'
  title: string;
  description: string;
  keywords: string;
}

import { useRemoteDataStore } from '@/context/RemoteDataContext';

export interface SeoGlobalSettings {
  siteName: string;
  defaultTitle: string;
  defaultDescription: string;
  defaultKeywords: string;
  ogImage: string;
  companyName: string;
  companyAddress: string;
  companyPhone: string;
  companyEmail: string;
  twitterHandle: string;
  facebookUrl: string;
  linkedinUrl: string;
}

export interface SeoSettings {
  global: SeoGlobalSettings;
  pages: SeoPageSettings[];
  updatedAt: number;
}

const DEFAULT_GLOBAL: SeoGlobalSettings = {
  siteName: 'OWELL Lighting',
  defaultTitle: 'OWELL Lighting - LED Sensor Light Manufacturer & Supplier',
  defaultDescription: 'OWELL is a professional LED infrared sensor light manufacturer in China. We provide high-quality LED security lights, PIR motion sensor lights, solar sensor lights with CE, RoHS, ISO9001 certification.',
  defaultKeywords: 'LED sensor light, infrared sensor light, PIR motion sensor light, LED security light, solar sensor light, LED lighting manufacturer, China LED factory, OEM LED light',
  ogImage: '',
  companyName: 'OWELL Lighting Co., Ltd.',
  companyAddress: 'No.88 Industrial Zone, High-tech Development Area, Shenzhen, Guangdong, China 518000',
  companyPhone: '+86-138-0000-0000',
  companyEmail: 'sales@owell-lighting.com',
  twitterHandle: '@owelllighting',
  facebookUrl: '',
  linkedinUrl: '',
};

const DEFAULT_PAGES: SeoPageSettings[] = [
  { id: 'seo-page-home', pageKey: 'home', title: '', description: '', keywords: '' },
  { id: 'seo-page-products', pageKey: 'products', title: '', description: '', keywords: '' },
  { id: 'seo-page-about', pageKey: 'about', title: '', description: '', keywords: '' },
  { id: 'seo-page-contact', pageKey: 'contact', title: '', description: '', keywords: '' },
  { id: 'seo-page-privacy', pageKey: 'privacy', title: '', description: '', keywords: '' },
];

const DEFAULT_SETTINGS: SeoSettings = {
  global: DEFAULT_GLOBAL,
  pages: DEFAULT_PAGES,
  updatedAt: Date.now(),
};

function readLocalSeoSettings(): SeoSettings {
  try {
    const saved = scopedStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved) as SeoSettings;
      return {
        global: { ...DEFAULT_GLOBAL, ...parsed.global },
        pages: parsed.pages && parsed.pages.length > 0 ? parsed.pages : DEFAULT_PAGES,
        updatedAt: parsed.updatedAt || Date.now(),
      };
    }
  } catch {
    // ignore
  }
  return DEFAULT_SETTINGS;
}

export function useSeoSettings(options?: { preferRemote?: boolean }) {
  const preferRemote = options?.preferRemote ?? false;
  const remoteData = useRemoteDataStore<Partial<SeoSettings>>('seo');
  // 🔴 同步初始化：直接读 localStorage 作为初始值，避免首帧默认值 → 第二帧同值不同引用的重渲染
  const [settings, setSettings] = useState<SeoSettings>(() => {
    try {
      const saved = scopedStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved) as SeoSettings;
        return {
          global: { ...DEFAULT_GLOBAL, ...parsed.global },
          pages: parsed.pages && parsed.pages.length > 0 ? parsed.pages : DEFAULT_PAGES,
          updatedAt: parsed.updatedAt || Date.now(),
        };
      }
    } catch (err) {
      logger.warn('Failed to init SEO settings:', String(err));
    }
    return {
      global: DEFAULT_GLOBAL,
      pages: DEFAULT_PAGES,
      updatedAt: Date.now(),
    };
  });

  // loading 始终为 false：本地数据同步初始化完成
  const loading = false;

  const displaySettings = useMemo((): SeoSettings => {
    if (preferRemote && remoteData && typeof remoteData === 'object') {
      return {
        global: { ...DEFAULT_GLOBAL, ...(remoteData.global || {}) },
        pages: remoteData.pages && remoteData.pages.length > 0 ? remoteData.pages : DEFAULT_PAGES,
        updatedAt: (remoteData as any).updatedAt || Date.now(),
      };
    }
    return settings;
  }, [preferRemote, remoteData, settings]);

  // Save to storage
  const saveSettings = useCallback((newSettings: SeoSettings) => {
    try {
      const toSave = { ...newSettings, updatedAt: Date.now() };
      scopedStorage.setItem(STORAGE_KEY, JSON.stringify(toSave));
      setSettings(toSave);
      return true;
    } catch (err) {
      logger.error('Failed to save SEO settings:', String(err));
      return false;
    }
  }, []);

  const updateGlobal = useCallback((global: Partial<SeoGlobalSettings>) => {
    const updated = {
      ...settings,
      global: { ...settings.global, ...global },
    };
    return saveSettings(updated);
  }, [settings, saveSettings]);

  const updatePage = useCallback((pageKey: string, pageData: Partial<SeoPageSettings>) => {
    const updatedPages = settings.pages.map((p) =>
      p.pageKey === pageKey ? { ...p, ...pageData } : p
    );
    const updated = { ...settings, pages: updatedPages };
    return saveSettings(updated);
  }, [settings, saveSettings]);

  const getPageSettings = useCallback((pageKey: string): SeoPageSettings | undefined => {
    return settings.pages.find((p) => p.pageKey === pageKey);
  }, [settings.pages]);

  const resetToDefaults = useCallback(() => {
    return saveSettings(DEFAULT_SETTINGS);
  }, [saveSettings]);

  return {
    settings: displaySettings,
    loading,
    updateGlobal,
    updatePage,
    getPageSettings,
    resetToDefaults,
    saveSettings,
    isUsingRemoteData: preferRemote && !!remoteData,
  };
}
